  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { authApi } from '../lib/api/auth';
  5→import { vaultApi } from '../lib/api/vault';
  6→import { useAuthStore } from '../stores/auth.store';
  7→import { useVaultStore } from '../stores/vault.store';
  8→import { useFolderStore } from '../stores/folder.store';
  9→import { useSyncStore } from '../stores/sync.store';
 10→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 11→import { useMfaStore } from '../stores/mfa.store';
 12→import {
 13→  initializeVault,
 14→  encryptVaultKeys,
 15→  decryptVaultKeys,
 16→  deriveIpnsName,
 17→  hexToBytes,
 18→  bytesToHex,
 19→} from '@cipherbox/crypto';
 20→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 21→import { detectDeviceInfo } from '../lib/device/info';
 22→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 23→import { clearFileSizeCache } from './useFileSize';
 24→
 25→export function useAuth() {
 26→  const navigate = useNavigate();
 27→  const {
 28→    isLoggedIn: coreKitLoggedIn,
 29→    isInitialized: coreKitInitialized,
 30→    isRequiredShare,
 31→    loginWithGoogle: coreKitLoginGoogle,
 32→    loginWithEmailOtp: coreKitLoginEmail,
 33→    loginWithWallet: coreKitLoginWallet,
 34→    getVaultKeypair,
 35→    getPublicKeyHex,
 36→    logout: coreKitLogout,
 37→  } = useCoreKitAuth();
 38→  const {
 39→    accessToken,
 40→    isAuthenticated,
 41→    lastAuthMethod,
 42→    userEmail,
 43→    setAccessToken,
 44→    setLastAuthMethod,
 45→    setUserEmail,
 46→    setVaultKeypair,
 47→    logout: clearAuthState,
 48→  } = useAuthStore();
 49→
 50→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 51→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 52→  const restoringRef = useRef(false);
 53→
 54→  // Stable refs for functions used in the session restoration effect.
 55→  // This prevents the effect from re-firing when function references change.
 56→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 57→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 58→
 59→  // Pending auth state for REQUIRED_SHARE flow
 60→  // Stored so completeRequiredShare() can resume after factor input
 61→  const [pendingCipherboxJwt, setPendingCipherboxJwt] = useState<string | null>(null);
 62→  const [pendingAuthMethod, setPendingAuthMethod] = useState<string | null>(null);
 63→
 64→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 65→
 66→  // Get vault store actions
 67→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 68→
 69→  /**
 70→   * Initialize vault for new users or load existing vault keys.
 71→   * Called after successful backend authentication.
 72→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 73→   */
 74→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 75→    // Get user's secp256k1 keypair from Core Kit TSS export
 76→    const userKeypair = await getVaultKeypair();
 77→
 78→    if (!userKeypair) {
 79→      throw new Error('Failed to get vault keypair from Core Kit');
 80→    }
 81→
 82→    // Store keypair in auth store for crypto operations
 83→    setVaultKeypair(userKeypair);
 84→
 85→    try {
 86→      // Try to fetch existing vault
 87→      const existingVault = await vaultApi.getVault();
 88→
 89→      // Store TEE keys if available
 90→      if (existingVault.teeKeys) {
 91→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 92→      }
 93→
 94→      // Vault exists - decrypt keys and load into store
 95→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 96→      const decryptedVault = await decryptVaultKeys(
 97→        {
 98→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
 99→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
100→        },
101→        userKeypair.privateKey
102→      );
103→
104→      setVaultKeys({
105→        rootFolderKey: decryptedVault.rootFolderKey,
106→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
107→        rootIpnsName: existingVault.rootIpnsName,
108→        vaultId: existingVault.id,
109→      });
110→    } catch (error) {
111→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
112→
113→      if (is404) {
114→        // New user - initialize vault
115→        console.log(
116→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
117→        );
118→        const newVault = await initializeVault(userKeypair.privateKey);
119→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
120→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
121→
122→        const storedVault = await vaultApi.initVault({
